import { useState } from 'react';
import { Box, Flex, Input, Button, useToast } from '@chakra-ui/react';
import Iframe from 'react-iframe';
import isUrl from 'is-url';
import { useCopyToClipboard } from 'usehooks-ts';

const frameH = 350;

function Generator() {
  const [value, setValue] = useState('');
  const [valid, setValid] = useState(false);
  const [code, setCode] = useState('');
  const [copied, copy] = useCopyToClipboard();
  const toast = useToast();

  function changeValue(e) {
    setValue(e);
    const isValid = isUrl(e);
    setValid(isValid);
    if (isValid) {
      const HTML = `<iframe src=${value} id="c-iframe" width="100%" height="${frameH}px" style="position: relative; display: initial;"></iframe>`;
      setCode(HTML);
    }
    generate()
  }

  function generate() {
    const HTML = `<iframe src=${value} id="c-iframe" width="100%" height="${frameH}px" style="position: relative; display: initial;"></iframe>`;
    setCode(HTML);
    toast({
      title: 'Generated.',
      description: 'Code has been generated. Hover the frame to copy.',
      status: 'success',
      duration: 3000,
      isClosable: true,
      position: 'bottom',
    });
  }

  function drop() {
    navigator.clipboard
      .readText()
      .then(text => {
        changeValue(text);
      })
      .catch(err => {
        console.error('Failed to read clipboard contents: ', err);
      });
  }

  function runCopy() {
    copy(code);
    toast({
      title: 'Copied.',
      description: 'Code has been copied.',
      status: 'success',
      duration: 3000,
      isClosable: true,
      position: 'bottom',
    });
  }

  return (
    <Box textAlign="center" fontSize="xl">
      <Box minH="100vh" p={3}>
        <Flex w="100%" h="100vh" justifyContent={'center'} alignItems="center">
          <Box
            borderWidth={1}
            borderStyle="solid"
            borderColor="gray.300"
            p={5}
            rounded="md"
            w={600}
          >
            <Box
              w="100%"
              h={frameH}
              rounded="md"
              overflow={'hidden'}
              pos="relative"
              bg="gray.300"
            >
              <Iframe
                url={value}
                width="100%"
                height={`${frameH}px`}
                id="c-iframe"
                display="initial"
                position="relative"
              />
              <Button
                pos="absolute"
                top="0"
                right="0"
                m={10}
                size="sm"
                bg="gray.900"
                color="white"
                _hover={{ bg: 'gray.800' }}
                _focus={{ bg: 'gray.800' }}
                _active={{ bg: 'gray.800' }}
                zIndex={2}
                onClick={() => runCopy()}
              >
                Get the code
              </Button>
              {valid && (
                <Flex
                  pos="absolute"
                  top="0"
                  left="0"
                  bg="rgba(193, 194, 197, .5)"
                  h={frameH}
                  w="100%"
                  display="flex"
                  justifyContent="center"
                  alignItems={'center'}
                >
                  <Button
                    bg="gray.900"
                    color="white"
                    _hover={{ bg: 'gray.800' }}
                    _focus={{ bg: 'gray.800' }}
                    _active={{ bg: 'gray.800' }}
                    onClick={() => runCopy()}
                  >
                    KOJI ME
                  </Button>
                </Flex>
              )}
            </Box>
            <Flex mt={5}>
              <Input
                w="100%"
                mr={2}
                variant="filled"
                placeholder="Paste your link here..."
                borderColor="gray.300"
                value={value}
                onChange={e => changeValue(e.target.value)}
              />
              <Button
                bg="gray.900"
                color="white"
                _hover={{ bg: 'gray.800' }}
                _focus={{ bg: 'gray.800' }}
                _active={{ bg: 'gray.800' }}
                onClick={() => drop()}
                w="250px"
              >
                Drop Your Koji Link
              </Button>
            </Flex>
          </Box>
        </Flex>
      </Box>
    </Box>
  );
}

export default Generator;
